const fs = require('fs');
const readline = require('readline');

async function extractSubscreens() {
  const filePath = 'C:\\Users\\mario\\.gemini\\antigravity\\brain\\92accbcb-9725-415b-bfa2-907fb2ea521c\\.system_generated\\logs\\transcript_full.jsonl';
  const fileStream = fs.createReadStream(filePath);
  const rl = readline.createInterface({ input: fileStream, crlfDelay: Infinity });

  let foundHtmlChunks = [];

  for await (const line of rl) {
    if (line.includes('subscreen-security') || line.includes('subscreen-categories') || line.includes('subscreen-templates')) {
      try {
        const obj = JSON.parse(line);
        const str = JSON.stringify(obj);
        foundHtmlChunks.push({ step: obj.step_index, content: str });
      } catch(e) {}
    }
  }

  console.log('Found', foundHtmlChunks.length, 'chunks with subscreens');
  foundHtmlChunks.forEach(c => console.log('Step', c.step, 'Length:', c.content.length));
  fs.writeFileSync('scratch/subscreens_transcript.json', JSON.stringify(foundHtmlChunks, null, 2), 'utf8');
}
extractSubscreens();
"
